// route: 0 card button, 1 message, 2 ignore
const body = $json.body || {};
if (body.encrypt) return [{ json: { route: 2, response: {}, note: 'Encrypted events are not supported: clear the Encrypt Key in the Lark app.' } }];
if (body.type === 'url_verification') return [{ json: { route: 2, response: { challenge: body.challenge } } }];

const header = body.header || {};
const event = body.event || {};
if (header.event_type === 'card.action.trigger') {
  const value = (event.action && event.action.value) || {};
  return [{
    json: {
      route: 0,
      response: { toast: { type: 'info', content: 'On it' } },
      action: value.a,
      id: Number(value.id),
      token: value.t,
      operator: (event.operator && event.operator.open_id) || '',
      message_id: (event.context && event.context.open_message_id) || '',
    },
  }];
}
if (header.event_type === 'im.message.receive_v1') {
  const m = event.message || {};
  if (m.chat_type !== 'p2p') return [{ json: { route: 2, response: {} } }];
  return [{ json: { route: 1, response: {}, message_id: m.message_id, event_id: header.event_id } }];
}
return [{ json: { route: 2, response: {} } }];
